#include <algorithm>

struct MarketState {
    double price;
    int64_t market_volume_window;
    int64_t remaining_institutional_sell;
    double hft_net_inventory;
};

void simulate_flash_crash_tick(MarketState& s, int tick) {
    int64_t target_sell = static_cast<int64_t>(s.market_volume_window * 0.09);
    int64_t actual_sell = std::min(target_sell, s.remaining_institutional_sell);
    s.remaining_institutional_sell -= actual_sell;

    s.hft_net_inventory += actual_sell;
    int64_t hft_dump_volume = 0;
    if (s.hft_net_inventory > 500) {
        hft_dump_volume = static_cast<int64_t>(s.hft_net_inventory * 0.85);
        s.hft_net_inventory -= hft_dump_volume;
        s.price -= 1.85;
    }

    s.market_volume_window = actual_sell + hft_dump_volume + 1000;

    std::cout << "Tick " << std::setw(2) << tick
              << " | Price: $" << std::setw(7) << std::fixed << std::setprecision(2) << s.price
              << " | InstSell: " << std::setw(5) << actual_sell
              << " | HFTDump: " << std::setw(5) << hft_dump_volume
              << " | WindowVol: " << std::setw(6) << s.market_volume_window
              << " | HFTInv: " << std::setw(5) << s.hft_net_inventory << "\n";
}

int main() {
    std::cout << "=== 2010 FLASH CRASH VOLUME PARTICIPATION FEEDBACK SIMULATOR ===\n";
    MarketState state{1160.00, 10000, 75000, 0.0};
    for (int t = 1; t <= 5; ++t) {
        simulate_flash_crash_tick(state, t);
    }
    std::cout << "Market state successfully deconstructed.\n";
    return 0;
}

