struct OrderEvent {
    uint64_t order_id;
    bool is_buy;
    double price;
    uint32_t qty;
    int64_t submit_ns;
    int64_t cancel_ns;
    bool executed;
};

class MicrostructureForensicTracker {
public:
    void record_order(const OrderEvent& ev) {
        events_.push_back(ev);
        if (ev.executed) total_trades_++;
        else total_quotes_++;
    }

    double quote_to_trade_ratio() const {
        if (total_trades_ == 0) return static_cast<double>(total_quotes_);
        return static_cast<double>(total_quotes_) / total_trades_;
    }

    bool detect_spoofing_signature(double qtr_threshold, int64_t max_lifespan_ns) const {
        double qtr = quote_to_trade_ratio();
        int short_lived_cancels = 0;
        for (const auto& ev : events_) {
            if (!ev.executed && ev.cancel_ns > 0) {
                int64_t lifespan = ev.cancel_ns - ev.submit_ns;
                if (lifespan < max_lifespan_ns) {
                    short_lived_cancels++;
                }
            }
        }
        bool high_qtr = (qtr >= qtr_threshold);
        bool high_cancels = (short_lived_cancels >= 5);
        return high_qtr && high_cancels;
    }

private:
    std::vector<OrderEvent> events_;
    uint64_t total_quotes_{0};
    uint64_t total_trades_{0};
};

int main() {
    std::cout << "=== PHANTOM LIQUIDITY & SPOOFING FORENSICS ===\n";
    MicrostructureForensicTracker tracker;
    for (uint64_t i = 1; i <= 20; ++i) {
        tracker.record_order({i, false, 1162.50, 500, 1000000 * static_cast<int64_t>(i), 1000000 * static_cast<int64_t>(i) + 45000000, false});
    }
    tracker.record_order({21, true, 1160.00, 10, 25000000, 0, true});

    std::cout << "Calculated Quote-to-Trade Ratio: " << std::fixed << std::setprecision(1) << tracker.quote_to_trade_ratio() << ":1\n";
    bool spoof_detected = tracker.detect_spoofing_signature(15.0, 100000000);
    std::cout << "Spoofing Pattern Detected: " << (spoof_detected ? "TRUE [ALERT: PHANTOM WALL]" : "FALSE") << "\n";
    return 0;
}

