#include <iostream>
#include <iomanip>
#include <string>
#include <unordered_map>
#include <cstdint>

struct OutboundOrder {
    uint64_t order_id;
    std::string symbol;
    bool is_buy;
    double price;
    uint32_t qty;
    int64_t submit_time_ns;
};

class RegulatoryComplianceGate {
public:
    explicit RegulatoryComplianceGate(int64_t min_quote_lifetime_ns) 
        : min_quote_lifetime_ns_(min_quote_lifetime_ns) {}

    bool approve_submission(const OutboundOrder& ord) {
        for (const auto& [id, resting] : active_orders_) {
            if (resting.symbol == ord.symbol && resting.is_buy != ord.is_buy && resting.price == ord.price) {
                std::cout << "[COMPLIANCE REJECT] Self-cross wash trade detected on " << ord.symbol << " at $" << ord.price << "\n";
                return false;
            }
        }
        active_orders_[ord.order_id] = ord;
        return true;
    }

    bool approve_cancellation(uint64_t order_id, int64_t cancel_time_ns) {
        auto it = active_orders_.find(order_id);
        if (it == active_orders_.end()) return false;

        int64_t lifespan_ns = cancel_time_ns - it->second.submit_time_ns;
        if (lifespan_ns < min_quote_lifetime_ns_) {
            std::cout << "[COMPLIANCE REJECT] Rapid quote flickering cancel blocked! Lifespan: " 
                      << (lifespan_ns / 1000000.0) << " ms (Min required: " 
                      << (min_quote_lifetime_ns_ / 1000000.0) << " ms)\n";
            return false;
        }
        active_orders_.erase(it);
        return true;
    }

private:
    int64_t min_quote_lifetime_ns_;
    std::unordered_map<uint64_t, OutboundOrder> active_orders_;
};

int main() {
    std::cout << "=== PRE-SUBMISSION BEHAVIORAL COMPLIANCE GATE ===\n";
    RegulatoryComplianceGate gate(50000000);

    OutboundOrder buy1{101, "AAPL", true, 180.50, 100, 100000000};
    gate.approve_submission(buy1);

    OutboundOrder sell_wash{102, "AAPL", false, 180.50, 100, 105000000};
    gate.approve_submission(sell_wash);

    gate.approve_cancellation(101, 115000000);
    bool ok = gate.approve_cancellation(101, 180000000);
    std::cout << "Legitimate cancellation approved: " << (ok ? "TRUE" : "FALSE") << "\n";
    return 0;
}
